const crypto = require('crypto');
const item = $input.first();
const fail = (reason) => [{ json: { ok: false, reason } }];
let raw;
if (item.binary?.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}
const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret) throw new Error('CONVEX_TO_N8N_SECRET is not configured');
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const received = String(headers['x-lendloop-signature'] || '');
if (!timestamp || !received) return fail('missing_headers');
if (!/^\d+$/.test(timestamp) || !received.startsWith('v1=')) return fail('invalid_signature');
if (Math.abs(Date.now() - Number(timestamp)) > 300000) return fail('stale_timestamp');
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(received.toLowerCase());
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('invalid_signature');
let payload;
try { payload = JSON.parse(raw); } catch (e) { return fail('invalid_signature'); }
return [{ json: { ok: true, ...payload } }];

const p = $input.first().json;
const { toolName, startDate, endDate } = p.loan;
// Readable dates for people: "Mon 16 Nov 2026", and "Sat 14 Nov to Mon 16 Nov 2026" for a range.
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MO = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const day = (iso, withYear = true) => {
  const [y, m, d] = iso.split('-').map(Number);
  const wd = WD[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
  return wd + ' ' + d + ' ' + MO[m - 1] + (withYear ? ' ' + y : '');
};
const range = startDate === endDate
  ? day(startDate)
  : day(startDate, startDate.slice(0, 4) !== endDate.slice(0, 4)) + ' to ' + day(endDate);
const who = p.counterpartFirstName;
const copy = {
  'loan.requested': [
    'New borrow request for ' + toolName,
    who + ' wants to borrow your ' + toolName + ' for ' + range + '. Open ' + p.appUrl + ' to approve or decline.',
  ],
  'loan.approved': [
    'Your request for ' + toolName + ' is approved',
    who + ' approved your request for ' + range + '. Enjoy, and please return it by ' + day(endDate) + '.',
  ],
  'loan.declined': [
    'Your request for ' + toolName + ' was declined',
    who + ' declined your request for ' + range + '.',
  ],
  'loan.returned': [
    toolName + ' marked as returned',
    who + ' marked ' + toolName + ' as returned. Thanks for lending responsibly.',
  ],
  'loan.cancelled': [
    'Request for ' + toolName + ' was cancelled',
    who + ' cancelled their request for ' + range + '.',
  ],
};
const entry = copy[p.type];
if (!entry) throw new Error('Unknown event type: ' + p.type);
return [{ json: { to: p.recipient.email, subject: entry[0], text: entry[1], eventId: p.eventId, loanId: p.loan.id } }];

const ctx = $('Build message').item.json;
const res = $input.item.json;
const code = Number(res.statusCode);
if (code >= 200 && code < 300) {
  return { json: { status: 'sent', channel: 'email', providerMessageId: res.body && res.body.id, severe: false } };
}
const severe = code >= 500 || code === 429;
const detail = (res.body && (res.body.message || res.body.name)) || 'request rejected';
const error = code + ' ' + detail;
console.log('[LendLoop mock notification] Resend rejected the email, falling back to mock', JSON.stringify({ error, to: ctx.to, subject: ctx.subject, text: ctx.text }));
return { json: { status: 'failed', channel: 'mock', error, severe } };

const ctx = $('Build message').item.json;
console.log('[LendLoop mock notification]', JSON.stringify({ to: ctx.to, subject: ctx.subject, text: ctx.text }));
// The message is part of the output so it can be read in the Executions view; Sign write-back sends only status fields to Convex.
return { json: { status: 'sent', channel: 'mock', severe: false, mockNotification: { to: ctx.to, subject: ctx.subject, text: ctx.text } } };

const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not configured');
const sign = (body) => {
  const timestamp = String(Date.now());
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { timestamp, signature };
};
const ctx = $('Build message').item.json;
const result = $input.item.json;
const body = JSON.stringify({ eventId: ctx.eventId, channel: result.channel, status: result.status, providerMessageId: result.providerMessageId, error: result.error, sentAt: new Date().toISOString() });
return { json: { body, ...sign(body), idempotencyKey: ctx.eventId, severe: result.severe === true, error: result.error } };

if ($('Sign write-back').item.json.severe === true) {
  throw new Error('Email provider failure: ' + $('Sign write-back').item.json.error);
}
return { json: $input.item.json };
